private void btnCalculateActionPerformed(java.awt.event.ActionEvent evt) {
    try {
        double units = Double.parseDouble(txtUnits.getText().trim());
        if (units < 0) {
            javax.swing.JOptionPane.showMessageDialog(this, 
                "Units consumed cannot be negative!", "Input Error", 
                javax.swing.JOptionPane.WARNING_MESSAGE);
            return;
        }

        // Step 1: Tariff Rate from Radio Buttons
        double ratePerUnit = 5.00; // Default Domestic
        if (rbCommercial.isSelected()) {
            ratePerUnit = 9.00;
        }

        // Step 2: Base Bill
        double baseBill = units * ratePerUnit;

        // Step 3: Check Surcharge
        double surcharge = 0.0;
        if (chkSurcharge.isSelected()) {
            surcharge = baseBill * 0.10; // 10% surcharge
        }

        // Step 4: Final Net Bill
        double netBill = baseBill + surcharge;

        // Step 5: Display
        txtNetBill.setText(String.format("₹ %.2f", netBill));

    } catch (NumberFormatException ex) {
        javax.swing.JOptionPane.showMessageDialog(this, 
            "Please enter valid numeric units!", "Error", 
            javax.swing.JOptionPane.ERROR_MESSAGE);
    }
}
```

