import java.util.Scanner;

public class PalindromeString {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter string: ");
        String original = scanner.nextLine();

        String cleanStr = original.trim().toLowerCase();
        String reversed = "";

        for (int i = cleanStr.length() - 1; i >= 0; i--) {
            reversed += cleanStr.charAt(i);
        }

        if (cleanStr.equals(reversed)) {
            System.out.println("\"" + original + "\" is a Palindrome String!");
        } else {
            System.out.println("\"" + original + "\" is NOT a Palindrome String.");
        }
        scanner.close();
    }
}
```
